    /**
     * Parse Canvas date string robustly, handling both timezone-aware and timezone-naive formats
     * [user] dateStr the Canvas date string to parse
     * [user] parsed Instant or null if parsing fails
     */
    private Instant parseCanvasDate(String dateStr) {
        if (dateStr == null || dateStr.trim().isEmpty()) {
            return null;
        }

        String trimmed = dateStr.trim();
        try {
            // Already timezone-aware (Z or ±HH:MM)
            if (trimmed.endsWith("Z") || trimmed.matches(".*[+-]\\d{2}:\\d{2}$")) {
                return Instant.parse(trimmed);
            }
            // If ends with ±HHMM, insert colon before parse
            if (trimmed.matches(".*[+-]\\d{4}$")) {
                String fixed = trimmed.replaceFirst("([+-]\\d{2})(\\d{2})$", "$1:$2");
                return Instant.parse(fixed);
            }
            // No timezone info: assume UTC
            LocalDateTime ldt = LocalDateTime.parse(trimmed);
            return ldt.atOffset(ZoneOffset.UTC).toInstant();
        } catch (Exception e) {
            log.debug("Failed to parse Canvas date: {}", dateStr, e);
            return null;
        }
    }
```

</details>

