    [user]
    public boolean containsSecurityViolations(String content, Level level) {
        // Treat null, empty, or whitespace-only input as safe
        if (StringUtils.isBlank(content)) return false;

        // Use system-configured default when level is null or DEFAULT
        Level effective = (level == null || Level.DEFAULT.equals(level))
                ? (defaultLowSecurity() ? Level.LOW : Level.HIGH)
                : level;
        AntiSamy scanner = (effective == Level.LOW) ? antiSamyLow : antiSamyHigh;
        try {
            CleanResults results = scanner.scan(content);
            boolean hasViolations = results.getNumberOfErrors() > 0;
            // Only log the number of violations at DEBUG level
            log.debug("AntiSamy found {} violations", results.getNumberOfErrors());
            return hasViolations;
        } catch (Exception e) {
            // Fail closed to avoid admitting unchecked content
            log.error("containsSecurityViolations: AntiSamy scan failed; failing closed.", e);
            return true;
        }
    }
```

