            byte[] buffer = new byte[CHUNK_SIZE];
            int bytesReadFirst;

            try {
                bytesReadFirst = readFully(stream, buffer);
                if (bytesReadFirst == 0) {
                    Blob empty = store.blobBuilder(can.name)
                        .userMetadata(ImmutableMap.of("id", asciiID, "path", filePath))
                        .payload(new byte[0])
                        .contentLength(0L)
                        .build();
                    store.putBlob(can.container, empty);
                    return 0L;
                }

                MultipartUpload mpu = store.initiateMultipartUpload(
                    can.container,
                    store.blobBuilder(can.name)
                        .userMetadata(ImmutableMap.of("id", asciiID, "path", filePath))
                        .build().getMetadata(),
                    PutOptions.NONE
                );

                List<MultipartPart> parts = new ArrayList<>();
                long totalSize = 0;
                int partNumber = 1;

                // upload first part
                Payload part1 = Payloads.newByteArrayPayload(Arrays.copyOf(buffer, bytesReadFirst));
                parts.add(store.uploadMultipartPart(mpu, partNumber++, part1));
                totalSize += bytesReadFirst;
                part1.release();

                int bytesRead;
                while ((bytesRead = readFully(stream, buffer)) > 0) {
                    // Create a payload for this part
                    Payload partPayload = Payloads.newByteArrayPayload(Arrays.copyOf(buffer, bytesRead));
                    // Upload this part
                    MultipartPart part = store.uploadMultipartPart(
                        mpu,
                        partNumber,
                        partPayload
                    );
                    parts.add(part);
                    totalSize += bytesRead;
                    partNumber++;
                    partPayload.release();
                }

                // Complete the multipart upload
                store.completeMultipartUpload(mpu, parts);
