	/**
	 * Validates if the content is actually valid XHTML
	 */
	private boolean isValidXHTML(InputStream stream) {
		try {
			stream.mark(2048);
			byte[] buffer = new byte[1024];
			int bytesRead = stream.read(buffer);
			stream.reset();

			if (bytesRead <= 0) {
				return false;
			}

			String content = new String(buffer, 0, bytesRead, StandardCharsets.UTF_8);
			String contentLower = content.toLowerCase(Locale.ROOT);

			// HTML5 DOCTYPE indicates HTML, not XHTML
			if (Pattern.compile("(?is)<!doctype\\s+html>").matcher(content).find()) {
				return false;
			}

			// Treat as XHTML when the root declares the XHTML namespace,
			// or when both XML declaration and XHTML DTD are present
			boolean hasXmlDeclaration = contentLower.contains("<?xml");
			boolean hasXhtmlDoctype = contentLower.contains("dtd xhtml") || contentLower.contains("//w3c//dtd xhtml");
			boolean hasXhtmlNamespace = contentLower.contains("xmlns=\"http://www.w3.org/1999/xhtml\"")
					|| contentLower.contains("xmlns='http://www.w3.org/1999/xhtml'");

			return hasXhtmlNamespace || (hasXmlDeclaration && hasXhtmlDoctype);

		} catch (IOException e) {
			log.debug("Error validating XHTML for content: {}", e.toString());
			return false;
		}
	}
```

</details>

