```suggestion
    // Publish‐after‐populate to avoid races; volatile for visibility
    private volatile Map<String, EntityCodec> codecs;

    private EntityCodec getCodec(String format) {
        Map<String, EntityCodec> local = codecs;
        if (local == null) {
            // Fully populate before assigning to the shared field
            Map<String, EntityCodec> initialized = new ConcurrentHashMap<>();
            initialized.put(Formats.JSON, new JsonCodec());
            initialized.put(Formats.XML, new XmlCodec());
            initialized.put(Formats.HTML, new HtmlCodec());
            local = initialized;
            codecs = local;
        }
        EntityCodec codec = local.get(format);
        if (codec == null) {
            throw new IllegalArgumentException(
                "Failed to find an encoder/decoder for format: " + format);
        }
        return codec;
    }
```

</details>

