    [user]
    [user](readOnly = true)
    public List<Poll> findOpenPollsForSites(List<String> siteIds, Date now, boolean asc) {
        if (siteIds == null || siteIds.isEmpty()) return List.of();
        if (now == null) throw new IllegalArgumentException("now must not be null");
        CriteriaBuilder cb = session().getCriteriaBuilder();
        CriteriaQuery<Poll> cq = cb.createQuery(Poll.class);
        Root<Poll> root = cq.from(Poll.class);
        Predicate inSites = root.get("siteId").in(siteIds);
        Predicate openOk = cb.or(
            cb.isNull(root.get("voteOpen")),
            cb.lessThanOrEqualTo(root.get("voteOpen"), now)
        );
        Predicate closeOk = cb.or(
            cb.isNull(root.get("voteClose")),
            cb.greaterThanOrEqualTo(root.get("voteClose"), now)
        );
        cq.where(cb.and(inSites, openOk, closeOk));
        cq.select(root)
          .orderBy(asc
              ? cb.asc(root.get("creationDate"))
              : cb.desc(root.get("creationDate"))
          );
        return session().createQuery(cq).getResultList();
    }
```

