```suggestion
      const copyPermissionControls = toolRow.querySelectorAll(`input[name$="-import-option-copy.permissions"]`);
      copyPermissionControls?.forEach(element => {
        // Cache the original disabled state rendered by the server
        element.dataset.originallyDisabled = element.disabled ? "true" : "false";

        element.addEventListener('click', (event) => {
          copyPermissionControls.forEach(el => {
            if (el === event.currentTarget) {
              return;
            }

            const originallyDisabled = el.dataset.originallyDisabled === "true";
            if (event.target.checked) {
              // When checking, disable peers that were not originally disabled
              if (!originallyDisabled) {
                el.disabled = true;
                el.checked = false;
              }
            } else {
              // When unchecking, restore each to its original state
              el.disabled = originallyDisabled;
            }
          });

          // Always keep the clicked control enabled
          event.currentTarget.disabled = false;
        });
      });

      const copySettingsControls = toolRow.querySelectorAll(`input[name$="-import-option-copy.settings"]`);
      copySettingsControls?.forEach(element => {
        // Cache the original disabled state rendered by the server
        element.dataset.originallyDisabled = element.disabled ? "true" : "false";

        element.addEventListener('click', (event) => {
          copySettingsControls.forEach(el => {
            if (el === event.currentTarget) {
              return;
            }

            const originallyDisabled = el.dataset.originallyDisabled === "true";
            if (event.target.checked) {
              // When checking, disable peers that were not originally disabled
              if (!originallyDisabled) {
                el.disabled = true;
                el.checked = false;
              }
            } else {
              // When unchecking, restore each to its original state
              el.disabled = originallyDisabled;
            }
          });

          // Always keep the clicked control enabled
          event.currentTarget.disabled = false;
        });
      });
```

