```java
// Add class-level cache
private static final Map<Class<?>, String> idFieldCache = new ConcurrentHashMap<>();

[user]
public List<T> findAllByIds(List<ID> ids) {
    if (ids == null || ids.isEmpty()) return List.of();

    String idField = idFieldCache.computeIfAbsent(domainClass, clazz -> {
        try {
            EntityType<T> entityType = sessionFactory.getMetamodel().entity(clazz);

            // Check for composite keys
            if (entityType.getIdType().getPersistenceType() == Type.PersistenceType.EMBEDDABLE) {
                throw new UnsupportedOperationException(
                    "findAllByIds does not support composite/embedded IDs for entity: " + clazz.getName());
            }

            return entityType.getId(entityType.getIdType().getJavaType()).getName();
        } catch (IllegalArgumentException e) {
            log.error("Failed to resolve ID field for entity: {}", clazz.getName(), e);
            throw new IllegalStateException("Entity " + clazz.getName() + " does not have a valid ID mapping", e);
        }
    });

    CriteriaBuilder cb = sessionFactory.getCriteriaBuilder();
    CriteriaQuery<T> query = cb.createQuery(domainClass);
    Root<T> root = query.from(domainClass);

    query.select(root).where(root.get(idField).in(ids));

    return sessionFactory.getCurrentSession()
            .createQuery(query)
            .getResultList();
}
```

