        if (submission == null || submission.getAssignment() == null) {
            log.warn("Cannot build release-grade replacements: submission or assignment is null for siteId={}", siteId);
            return map;
        }
        try {
            Assignment assignment = submission.getAssignment();
            Site site = siteService.getSite(siteId);
            map.put("siteTitle", site.getTitle());
            map.put("siteUrl", site.getUrl());
            map.put("title", assignment.getTitle());
            map.put("url", getAssignmentUrl(assignment));
            map.put("bundle", resourceLoader);
        } catch (Exception e) {
            log.warn("Failed to get email replacements", e);
        }
        return map;
    }
```

