  public static ImportNormalization normalizeForImport(Date dueDate, Date retractDate, Integer lateHandling,
      Date feedbackStartDate, Date feedbackEndDate) {
    Date cutoffDate = getFeedbackCutoffDate(dueDate, retractDate, lateHandling);
    if (cutoffDate == null) {
      return ImportNormalization.removeFeedback();
    }

    Date normalizedStartDate = feedbackStartDate == null || feedbackStartDate.before(cutoffDate)
        ? cutoffDate
        : feedbackStartDate;
    Date normalizedEndDate = normalizeImportedFeedbackEndDate(
        cutoffDate, normalizedStartDate, feedbackStartDate, feedbackEndDate);
    return ImportNormalization.apply(normalizedStartDate, normalizedEndDate);
  }

  private static Date normalizeImportedFeedbackEndDate(Date cutoffDate, Date normalizedStartDate,
      Date feedbackStartDate, Date feedbackEndDate) {
    if (feedbackEndDate == null) {
      return null;
    }

    if (feedbackStartDate == null) {
      return cutoffDate;
    }

    if (feedbackStartDate.before(cutoffDate) && feedbackEndDate.after(feedbackStartDate)) {
      long feedbackWindow = feedbackEndDate.getTime() - feedbackStartDate.getTime();
      return new Date(cutoffDate.getTime() + feedbackWindow);
    }

    return feedbackEndDate.before(normalizedStartDate) ? normalizedStartDate : feedbackEndDate;
  }
```

